#include "resident/domains/military/military_model.hpp"
// 军籍有限页面只投影当前双重任职、原人口与军籍收据；按钮仍通过同一正式预览复核。
#include "population_military.hpp"
#include <algorithm>
#include <map>
#include <tuple>
namespace hanmo::resident {
namespace {
using V=BoundaryValue;using A=V::Array;using D=V::Dict;
// 既有军事向量以稳定ID查询，缺失目录不被页面补成可用单位。
template<class T>const T* entry(const std::vector<T>& rows,const StableId& id){for(const auto& row:rows)if(row.id==id)return &row;return nullptr;}
// 状态只作标题映射，页面不改变训练或现役资格。
const char* status_name(PopulationStatus status){switch(status){case PopulationStatus::civilian:return "civilian";case PopulationStatus::training:return "training";case PopulationStatus::trained_reserve:return "trained_reserve";case PopulationStatus::serving:return "serving";case PopulationStatus::wounded:return "wounded";case PopulationStatus::captive:return "captive";case PopulationStatus::displaced:return "displaced";}return "unknown";}
// 行动权限完整输出实际epoch和本人身份，不能由界面目录合成另一份授权。
V authority_value(const ActingAuthority& authority){return V{D{{"organization_id",V{authority.organization_id}},{"office_id",V{authority.office_id}},{"authority_epoch",V{authority.authority_epoch}},{"actor_id",V{authority.actor_id}}}};}
// 仅计算当前群体仍被真实生产分配占用的劳力，退籍不会据此重建任何旧分配。
Integer allocated_labor(const PopulationMilitaryReadContext& ctx,const StableId& cohort){Integer used=0;for(const auto& row:ctx.economy.labor_allocations.rows())if(row.second.cohort_id==cohort&&row.second.from_tick<=ctx.common.tick()&&row.second.through_tick>=ctx.common.tick())used+=row.second.workers;return used;}
// 历史旧债和接收后的新工资并列保留，各自显示真实付款方与启用状态。
std::vector<StableId> wage_ids(const PopulationMilitaryReadContext& ctx,const PopulationMilitarySource& source){auto ids=source.wage_obligation_ids;for(const auto& row:ctx.state.integration_facts.rows())if(row.second.source_id==source.id)for(const auto& id:row.second.new_wage_obligation_ids)if(std::find(ids.begin(),ids.end(),id)==ids.end())ids.push_back(id);return ids;}
// 工资显示整数作者率和真实容器引用，不把应付或欠额误写成另一份可花资产。
A wages(const PopulationMilitaryReadContext& ctx,const PopulationMilitarySource& source){A rows;for(const auto& id:wage_ids(ctx,source)){const auto* wage=ctx.economy.obligations.find(id);const auto* rate=wage?ctx.economy_catalog.rates.find(wage->rate_profile):nullptr;if(!wage||!rate)continue;Integer outstanding=0;for(const auto& row:ctx.economy.arrears.rows())if(row.second.obligation_id==id)outstanding+=row.second.original_due-row.second.paid_amount;const auto* cohort=ctx.economy.cohorts.find(wage->beneficiary.id);rows.emplace_back(V{D{{"obligation_id",V{id}},{"cohort_id",V{wage->beneficiary.id}},{"status",V{cohort?status_name(cohort->status):"unknown"}},{"payer_wallet_id",V{wage->source_wallet_or_inventory}},{"payee_wallet_id",V{wage->destination}},{"period_ticks",V{wage->period_ticks}},{"numerator",V{rate->numerator}},{"denominator",V{rate->denominator}},{"per_capita",V{rate->per_capita}},{"outstanding",V{outstanding}},{"active",V{wage->active}}}});}return rows;}
// 真实宏观责任按当前有效binding列出，军籍状态没有凭标签生成的宏观口粮。
A macro_food(const PopulationMilitaryReadContext& ctx,const PopulationMilitarySource& source){A rows;for(const auto& row:ctx.economy.provision_bindings.rows()){const auto& b=row.second;if(b.subject.kind!=SubjectKind::cohort||b.policy_owner!=ProvisionOwner::macro||b.from_tick>ctx.common.tick()||b.through_tick<ctx.common.tick())continue;if(b.subject.id!=source.reserve_cohort_id&&b.subject.id!=source.displaced_cohort_id)continue;rows.emplace_back(V{D{{"cohort_id",V{b.subject.id}},{"inventory_id",V{b.payer_inventory}},{"obligation_id",V{b.obligation_id}},{"policy_owner",V{"macro"}}}});}return rows;}
}
// 当事人在同一候选的军职与机构职务均有效才可见；军事口粮读取已证成员的实际营地、军团或羁押方。
Outcome<BoundaryValue> population_military_page(const PopulationMilitaryReadContext& ctx,const StableId& observer){
    if(!ctx.catalog.enabled||observer!=ctx.common.state().metadata.player_actor_id||!ctx.common.actor(observer))return {false,{},common_failure("PopulationMilitaryNotObservable").error};
    auto continuity=population_military_continuity(ctx);if(!continuity.ok)return {false,{},continuity.error};
    A rows;bool more=false;
    for(const auto& pair:ctx.catalog.sources.rows()){
        const auto& source=pair.second;auto service=population_military_release_authority(ctx,source,ctx.common.tick());if(!service.ok)return {false,{},service.error};const OfficeState* office=nullptr;const auto* military_office=entry(ctx.military.offices,service.value.military_office_id);if(!service.value.integration_receipt_id.empty()){auto location=ctx.common.resolved_location(observer);const auto* home=location.ok?std::get_if<SettlementLocation>(&location.value):nullptr;if(!home||home->place_id!=source.home_site_id)continue;for(const auto& candidate:ctx.organization.offices.rows()){const auto& current=candidate.second;if(current.organization_id!=service.value.organization_id||current.status!=OfficeStatus::active||current.holder_actor_id!=std::optional<StableId>(observer))continue;auto allowed=check_authority(ctx.common,ctx.organization,ctx.organization_catalog,{service.value.organization_id,current.id,current.epoch,observer},"release_reserve",{ScopeRef::Kind::site,source.home_site_id},1);if(allowed.ok){office=&current;break;}}}else office=ctx.organization.offices.find(source.organization_office_id);
        if(!office||office->status!=OfficeStatus::active||office->holder_actor_id!=std::optional<StableId>(observer)||!military_office||!military_office->enabled||military_office->holder_actor_id!=observer)continue;
        if(rows.size()>=64){more=true;break;}
        const auto* reserve=ctx.economy.cohorts.find(source.reserve_cohort_id);const auto* unit=entry(ctx.military.military_units,source.unit_id);const auto* garrison=entry(ctx.military_catalog.garrisons,source.garrison_id);if(!reserve||!unit||!garrison)return {false,{},common_failure("PopulationMilitarySourceUnavailable",source.id).error};
        const auto* definition=entry(garrison->units,source.unit_id);const auto count=[&](const StableId& id){const auto* cohort=ctx.economy.cohorts.find(id);return cohort?cohort->headcount:Integer(0);};
        const ActingAuthority authority{service.value.organization_id,office->id,office->epoch,observer};const auto* received=ctx.state.integration_facts.find(service.value.integration_receipt_id);
        D row{{"source_id",V{source.id}},{"unit_id",V{source.unit_id}},{"unit_name",V{definition&&definition->display_name?*definition->display_name:source.unit_id}},{"garrison_id",V{source.garrison_id}},{"garrison_name",V{garrison->display_name}},{"home_site_id",V{source.home_site_id}},{"household_group_id",V{source.household_group_id}},{"reserve_cohort_id",V{source.reserve_cohort_id}},{"reserve_status",V{status_name(reserve->status)}},{"reserve_count",V{reserve->headcount}},{"reserve_labor_count",V{reserve->labor_capacity}},{"allocated_labor_count",V{allocated_labor(ctx,reserve->id)}},{"allocatable_labor_count",V{std::max<Integer>(0,reserve->labor_capacity-allocated_labor(ctx,reserve->id))}},{"serving_count",V{count(source.serving_cohort_id)}},{"wounded_count",V{count(source.wounded_cohort_id)}},{"captive_count",V{count(source.captive_cohort_id)}},{"displaced_count",V{count(source.displaced_cohort_id)}},{"initial_training",V{source.initial_training}},{"initial_fatigue",V{source.initial_fatigue}},{"initial_morale",V{source.initial_morale}},{"service_consent_source_id",V{received?received->service_consent_source_id:source.service_consent_source_id}},{"wage_obligation_ids",boundary::string_array(wage_ids(ctx,source))},{"wages",V{wages(ctx,source)}},{"macro_food_sources",V{macro_food(ctx,source)}}};
        std::map<std::tuple<StableId,StableId,StableId,StableId>,Integer> food;
        for(const auto& proof:continuity.value.provisions)if(proof.source_id==source.id)++food[{proof.cohort_id,proof.inventory_id,proof.army_id,proof.garrison_id}];
        A military_food;for(const auto& item:food)military_food.emplace_back(V{D{{"cohort_id",V{std::get<0>(item.first)}},{"inventory_id",V{std::get<1>(item.first)}},{"army_id",V{std::get<2>(item.first)}},{"garrison_id",V{std::get<3>(item.first)}},{"member_count",V{item.second}},{"policy_owner",V{"military"}}}});row.emplace_back("military_food_sources",V{std::move(military_food)});
        PopulationEnrollCommand enroll;enroll.authority=authority;enroll.source_id=source.id;enroll.count=1;enroll.labor_count=reserve->labor_capacity>0?1:0;
        for(const auto& allocation:ctx.economy.labor_allocations.rows())if(allocation.second.cohort_id==reserve->id&&allocation.second.from_tick<=ctx.common.tick()&&allocation.second.through_tick>=ctx.common.tick())enroll.release_allocation_ids.push_back(allocation.first);
        auto quote=preview_population_military(ctx,observer,PopulationMilitaryCommand{enroll});row.emplace_back("enroll_code",V{quote.ok?StableId{}:quote.error.original.code});
        if(quote.ok)row.emplace_back("enroll_action",V{D{{"command",V{"population_enroll"}},{"params",V{D{{"authority",authority_value(authority)},{"source_id",V{source.id}},{"count",V{enroll.count}},{"labor_count",V{enroll.labor_count}},{"release_allocation_ids",boundary::string_array(enroll.release_allocation_ids)}}}}}});
        Integer dead_count=0;A releases,enrollments;for(const auto& item:ctx.state.enrollments.rows()){const auto& enrollment=item.second;if(enrollment.source_id!=source.id)continue;Integer fit=0,labor=0;for(const auto& member:enrollment.members)if(std::find(unit->dead.begin(),unit->dead.end(),member.member_id)!=unit->dead.end())++dead_count;for(const auto& member:enrollment.members)if(std::find(unit->fit.begin(),unit->fit.end(),member.member_id)!=unit->fit.end()){++fit;if(member.labor_eligible)++labor;}enrollments.emplace_back(V{D{{"enrollment_id",V{enrollment.id}},{"fit_count",V{fit}},{"labor_count",V{labor}}}});if(!fit)continue;PopulationReleaseCommand release;release.authority=authority;release.enrollment_id=enrollment.id;auto permitted=preview_population_military(ctx,observer,PopulationMilitaryCommand{release});if(permitted.ok)releases.emplace_back(V{D{{"enrollment_id",V{enrollment.id}},{"fit_count",V{fit}},{"labor_count",V{labor}},{"command",V{"population_release"}},{"params",V{D{{"authority",authority_value(authority)},{"enrollment_id",V{enrollment.id}}}}}}});}
        row.emplace_back("dead_count",V{dead_count});row.emplace_back("enrollments",V{std::move(enrollments)});row.emplace_back("release_actions",V{std::move(releases)});rows.emplace_back(V{std::move(row)});
    }
    return {true,V{D{{"rows",V{std::move(rows)}},{"has_more",V{more}}}},{}};
}
} // 无行动或目录全量泄漏；读取不分配ID、不扣工资、不授予服役资格。
